Two producers each put two tagged items and then a stop marker into one queue, two consumers take items until they see a stop marker, and the collected items are sorted before printing. What does this program print?

from queue import Queue
import threading

def produce(q, tag):
    for i in range(2):
        q.put(f'{tag}{i}')
    q.put(None)

def consume(q, out):
    while True:
        item = q.get()
        if item is None:
            return
        out.append(item)

q = Queue()
out = []
producers = [threading.Thread(target=produce, args=(q, t)) for t in ('a', 'b')]
for p in producers:
    p.start()
consumers = [threading.Thread(target=consume, args=(q, out)) for _ in range(2)]
for c in consumers:
    c.start()
for p in producers:
    p.join()
for c in consumers:
    c.join()
print(sorted(out), len(out))

A callable is built inside another function, and a program then tries to turn it into bytes, catching and naming the refusal before using the callable normally. What does this program print?

import pickle

def outer():
    def inner(n):
        return n * 3
    return inner

f = outer()
try:
    pickle.dumps(f)
except Exception as e:
    print(type(e).__name__)
print(callable(f), f(2))

A module-level function is handed to a pool of two processes for three values, and the same function is then called directly. What does this program print?

def squares(n):
    return n * n

def worker(n):
    return squares(n)

if __name__ == '__main__':
    from concurrent.futures import ProcessPoolExecutor
    with ProcessPoolExecutor(max_workers=2) as pool:
        got = list(pool.map(worker, [1, 2, 3]))
    print(got, squares(4))

A class declares the only two names its objects are allowed to carry, and the program then tries to give one object a third. What does this program print?

class Point:
    __slots__ = ('x', 'y')
    def __init__(self, x, y):
        self.x = x
        self.y = y

p = Point(1, 2)
print(p.x, p.y)
try:
    p.z = 3
except AttributeError:
    print('no z')
print(hasattr(p, '__dict__'))

