A helper fills a cache the first time a key is asked for and never looks at the store again, and the store is changed behind its back before the cache is cleared by hand. What does this program print?

store = {'a': 1, 'b': 2}
cache = {}

def get(key):
    if key not in cache:
        cache[key] = store[key] * 10
    return cache[key]

print(get('a'))
store['a'] = 5
print(get('a'))
cache.clear()
print(get('a'))

Eight numbers are searched twice for pairs that add to seven, once by comparing every pair and once by remembering what has been seen, and the printed line is the two work counts and the two pair counts. What does this program print?

data = [3, 1, 4, 1, 5, 9, 2, 6]

steps = 0
pairs = 0
for i in range(len(data)):
    for j in range(i + 1, len(data)):
        steps += 1
        if data[i] + data[j] == 7:
            pairs += 1

seen = {}
steps2 = 0
pairs2 = 0
for j, v in enumerate(data):
    steps2 += 1
    want = 7 - v
    if want in seen:
        pairs2 += seen[want]
    seen[v] = seen.get(v, 0) + 1
print(steps, steps2, pairs, pairs2)

Three worker threads each either do their work or fail, and each one handles its own failure, and the program waits for all of them and then sorts and counts what they recorded. What does this program actually print?

import threading

log = []

def worker(name, fail):
    try:
        if fail:
            raise ValueError(name)
        log.append('ok ' + name)
    except ValueError:
        log.append('failed ' + name)

threads = [threading.Thread(target=worker, args=(f'w{i}', i == 1)) for i in range(3)]
for t in threads:
    t.start()
for t in threads:
    t.join()
print(sorted(log), len(log))

A service has two checks, one about its own ability to run and one about whether everything it needs is reachable, and the second one is called with only the database reachable. What does this program actually print?

def ping(name, table):
    if name in table:
        return table[name]
    raise ConnectionError(name)

db_ok = {'db': True}
cache_ok = {}

def liveness():
    return ping('db', db_ok)

def readiness():
    ping('db', db_ok)
    if 'cache' not in cache_ok:
        raise ConnectionError('cache')
    return True

print('live', liveness())
try:
    print('ready', readiness())
except ConnectionError as e:
    print('not ready', e.args[0])

A list is handed to a pool of one process, and the work done on the far side appends to it and reports its length, and the calling process then prints that report and its own list. What does this program actually print?

from concurrent.futures import ProcessPoolExecutor

def grow(box):
    box.append('from worker')
    return len(box)

if __name__ == '__main__':
    box = ['from caller']
    with ProcessPoolExecutor(max_workers=1) as pool:
        got = pool.submit(grow, box).result()
    print(got, box)

Eight numbers are searched twice, once by comparing every pair and once by remembering what has been seen, and the printed number packs the first search's work in the hundreds and the second's work in the units. What number is printed?

data = [3, 1, 4, 1, 5, 9, 2, 6]
steps = 0
for i in range(len(data)):
    for j in range(i + 1, len(data)):
        steps += 1
seen = {}
steps2 = 0
for v in data:
    steps2 += 1
    seen[v] = seen.get(v, 0) + 1
print(steps * 100 + steps2)

A helper records a miss the first time a key is asked for and a hit every time after that, and six keys are asked for in a fixed order, and the printed number packs the misses in the hundreds and the hits in the units. What number is printed?

store = {'a': 1, 'b': 2, 'c': 3}
cache = {}
log = []

def get(key):
    if key in cache:
        log.append('hit')
        return cache[key]
    log.append('miss')
    cache[key] = store[key]
    return cache[key]

for key in ('a', 'b', 'a', 'c', 'b', 'a'):
    get(key)
print(log.count('miss') * 100 + log.count('hit'))

A source records every value it produces and yields a scaled value, and a filtering stage passes on only the values at or above thirty, and the printed number packs how many values the source produced in the thousands and the first value handed on in the units. What number is printed?

pulled = []

def source(n):
    for i in range(n):
        pulled.append(i)
        yield i * 10

def keep_large(nums):
    for v in nums:
        if v >= 30:
            yield v

pipe = keep_large(source(9))
first = next(pipe)
print(len(pulled) * 1000 + first)

Three instances are given traffic only when they report healthy and their version is one of the two the checker accepts, and the first instance is then replaced with the new version. Which pair names what this program prints and why?

instances = ['old', 'old', 'old']
traffic = [0, 0, 0]
ready = [True, True, True]

def check(version, healthy):
    return healthy and version in ('old', 'new')

def reassign():
    for i, version in enumerate(instances):
        if check(version, ready[i]):
            traffic[i] = 1
        else:
            traffic[i] = 0

reassign()
print(sum(traffic), traffic)
instances[0] = 'new'
reassign()
print(sum(traffic), traffic)
